use vstd::prelude::*;

verus! {

/// Parity (mod 2) for mathematical integers.
spec fn parity2(x: int) -> int {
    x % 2
}

/// Desired parity is N % 2 (as an integer).
spec fn desired_parity(N: u32) -> int {
    parity2(N as int)
}

/// The procedure: force every element to have parity equal to N's parity.
/// We do this by setting each element to 0 if N is even, else 1.
fn myfun(a: &mut Vec<i32>, N: u32)
    requires
        N > 0,
        a.len() == N as usize,
    ensures
        a.len() == N as usize,
        forall|i: int|
            0 <= i < N as int ==>
                parity2(a[i] as int) == desired_parity(N),
{
    let target: i32 = if (N % 2) == 0 { 0 } else { 1 };

    let mut i: u32 = 0;
    while i < N
        invariant
            // Preservation of length throughout execution
            a.len() == N as usize,
            // Counter stays in range
            i <= N,
            // All positions strictly before i already satisfy the parity property
            forall|j: int|
                0 <= j < i as int ==>
                    parity2(a[j] as int) == desired_parity(N),
        decreases N - i,
    {
        // Establish safe indexing facts for Vec update
        assert(i as usize < a.len());

        a.set(i as usize, target);

        // After setting, position i satisfies parity too
        assert(parity2(a[i as int] as int) == desired_parity(N)) by {
            // target is either 0 or 1 matching N%2
            if (N % 2) == 0 {
                assert(target == 0);
                assert(desired_parity(N) == parity2(N as int));
                // parity2(0) == 0, and N even => N%2 == 0
                assert(parity2(target as int) == 0);
                assert(desired_parity(N) == 0);
            } else {
                assert(target == 1);
                assert(desired_parity(N) == parity2(N as int));
                // parity2(1) == 1, and N odd => N%2 == 1
                assert(parity2(target as int) == 1);
                assert(desired_parity(N) == 1);
            }
        }

        i = i + 1;
    }
}

} // verus!

